@page "/shipments"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@rendermode InteractiveAuto
@inject HttpClient Http

<PageTitle>Shipments - Dispatcher View</PageTitle>

<h1>Shipment Dashboard</h1>

<div class="mb-3 row">
